import { Game, SUBJECTS, UPGRADES } from '../game/game';
import { LaboratoryRenderer } from '../render/laboratory';
import { EFFECTS, type Ingredient, type PotionMetrics, type Experiment } from '../core/types';
import { icon } from './icons';
import './styles.css';

type Tab = 'brew'|'explore'|'trials'|'journal'|'shop';
type Tool = 'pour'|'stir'|'crush'|'inspect';
type Hooks = {save:()=>void;newWorld:(seed:string)=>void;exportSave:()=>void;importSave:(file:File)=>void;sound:(event:string)=>void;setVolume:(n:number)=>void};
const esc=(s:unknown)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const nice=(s:string)=>s.replace(/-/g,' ').replace(/^\w/,c=>c.toUpperCase());
const num=(n:number,decimals=0)=>Number.isFinite(n)?n.toFixed(decimals):'—';
const meter=(value:number)=>Math.max(0,Math.min(100,value));
const effectColors:Record<string,string>={strength:'#b57a43',healing:'#5e925d',warmth:'#c97547',frost:'#6296a5',protection:'#b19b52',transformation:'#9371aa',attraction:'#b97692',energy:'#d0a74f',toxicity:'#849847'};

export function mountApp(root:HTMLElement,game:Game,hooks:Hooks):{update:(dt:number)=>void;destroy:()=>void} {
  let tab:Tab='brew',tool:Tool='stir',selected=game.world.ingredients.find(i=>(game.state.inventory[i.id]||0)>0)?.id||game.world.ingredients[0]?.id||'';
  let amount=24,region='garden',subject=SUBJECTS[0]?.id||'training-dummy',journalTab='experiments',phase='all';
  let modal='',modalId='',showForecast=false,diagnostics=false,elapsed=0,refresh=0,fps=60;
  let opener:HTMLElement|null=null;let lastVerification='';
  let pointer:{x:number;y:number}|null=null,dragging=false,lastPointer:{x:number;y:number}|null=null,toastTimeout=0,lastMessage='';
  root.innerHTML=`<div class="app-shell">
    <header class="app-header"><a class="brand" href="#" aria-label="Potion Brewer home"><span class="brand-mark">${icon('cauldron',28)}</span><span><strong>Potion Brewer</strong><small>THE MOONLIT APOTHECARY</small></span></a><div class="header-actions"><span class="coin-counter">${icon('coin',18)}<strong data-live="coins">${game.state.coins}</strong><span class="coin-label">gold</span></span><button class="icon-button" data-action="settings" aria-label="Settings">${icon('gear')}</button></div></header>
    <div class="world-strip"><span><i class="status-dot"></i><span data-live="rank">${game.rank}</span></span><span>Day <b data-live="day">${game.state.day}</b><span class="strip-separator">·</span><span data-live="reputation">${game.state.reputation}</span> reputation</span><span class="world-mode" data-live="mode">${game.state.mode==='sandbox'?'SANDBOX':'SHOP OPEN'}</span></div>
    <main id="game-main"><section data-panel="brew"></section><section data-panel="explore" hidden></section><section data-panel="trials" hidden></section><section data-panel="journal" hidden></section><section data-panel="shop" hidden></section></main>
    <nav class="main-nav" aria-label="Game areas">${(['brew','explore','trials','journal','shop'] as Tab[]).map((t,i)=>`<button data-action="navigate" data-tab="${t}" class="nav-button ${t==='brew'?'active':''}" ${t==='brew'?'aria-current="page"':''}>${icon(['cauldron','compass','flask','book','shop'][i],22)}<span>${nice(t)}</span></button>`).join('')}</nav>
    <div class="toast" id="toast-message" role="status" aria-live="polite"></div><div class="modal-layer" id="modal-layer" hidden></div><input type="file" id="save-file" accept="application/json,.json" hidden />
  </div>`;
  const panel=(t:Tab)=>root.querySelector<HTMLElement>(`[data-panel="${t}"]`)!;
  const ingredient=(id:string)=>game.world.ingredients.find(i=>i.id===id);
  const metrics=()=>game.sim.metrics();
  const topEffects=(i:Ingredient)=>(i.region==='laboratory'?[]:EFFECTS).filter(e=>e!=='toxicity'&&i.effects[e]>0).sort((a,b)=>i.effects[b]-i.effects[a]).slice(0,2);
  const swatch=(i:Ingredient,large=false)=>`<span class="ingredient-visual ${large?'large':''}" style="--ingredient:${esc(i.color)}">${icon(i.phase==='liquid'?'drop':i.phase==='gas'?'spark':i.phase==='solid'?'leaf':i.phase==='powder'?'spark':'drop',large?36:25)}</span>`;
  const effectChips=(i:Ingredient)=>topEffects(i).map(e=>`<span class="effect-chip" style="--effect-color:${effectColors[e]}">${nice(e)}</span>`).join('');
  const pageHeading=(eyebrow:string,title:string,description:string,extra='')=>`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;
  const resultRows=(values:Partial<PotionMetrics>)=>Object.entries(values).filter(([key])=>key!=='mass').map(([key,value])=>`<div class="result-row"><span>${esc(nice(key))}</span><div class="result-track"><i style="width:${meter(key==='temperature'?(value!+20)/1.2:key==='viscosity'?value!*10:key==='density'?value!*30:key==='homogeneity'?value!*100:value!)}%;background:${effectColors[key]||'#7c9588'}"></i></div><strong>${num(key==='homogeneity'?value!*100:value!,key==='viscosity'||key==='density'?1:0)}${key==='temperature'?'°C':key==='homogeneity'?'%':''}</strong></div>`).join('');
  const requestRows=()=>{
    const verified=game.currentVerification();
    return game.state.commission.requirements.map(r=>{
      const target=r.min!==undefined?`≥ ${num(r.min)}`:r.max!==undefined?`≤ ${num(r.max)}`:num(r.target??0);
      const actual=verified[r.property];
      const meets=actual!==undefined&&(r.min===undefined||actual>=r.min)&&(r.max===undefined||actual<=r.max)&&(r.target===undefined||Math.abs(actual-r.target)<=20);
      return `<div class="request-row"><span>${esc(r.label||nice(r.property))}</span><b>${target}${r.property==='temperature'?'°C':''}</b><span class="verification ${actual===undefined?'unknown':meets?'verified':'unmet'}">${actual===undefined?'Untested':`${num(actual,0)} ${meets?'✓':''}`}</span></div>`;
    }).join('');
  };
  function commissionHTML(){const c=game.state.commission;return `<div class="commission-card"><div class="commission-overline"><span>${icon('shop',15)} CURRENT COMMISSION</span><span>${icon('coin',15)} Up to ${c.budget}g</span></div><div class="customer"><span class="customer-portrait">${icon(c.role.includes('blacksmith')?'hammer':c.role.includes('herbalist')?'leaf':c.role.includes('courier')?'compass':c.role.includes('storyteller')?'book':c.role.includes('surveyor')?'spark':'star',26)}</span><div><h3>${esc(c.customer)}</h3><small>${esc(c.role)}</small></div></div><h2>${esc(c.title)}</h2><blockquote>“${esc(c.dialogue)}”</blockquote><div class="request-table">${requestRows()}</div><p class="fine-print">Your latest matching trial verifies a property. Bottling keeps the final mixture.</p><button class="button quiet full" data-action="navigate" data-tab="trials">${icon('flask',17)} Visit the trial room ${icon('arrow',16)}</button></div>`;}
  function hintHTML(){const t=game.state.tutorial;const hints=[['A little curiosity goes a long way.','Choose an ingredient below and add a measured amount. Its known properties are clues, not a recipe.'],['Bring your mixture to life.','Drag the spoon through the cauldron. Heat, mixing, and contact can change what emerges.'],['Let the evidence lead you.','Take a sample to the trial room. Different subjects reveal different properties.'],['A discovery worth keeping.','Use your trial results to refine the batch, then bottle it when you are ready.'],['Open for a little magic.','Deliver a bottle in the shop. Your payment depends on how well the potion meets the commission.']];if(t>=5)return `<div class="bench-note">${icon('spark',18)} <span>Every batch has a story. Keep notes, test often, and follow the changes.</span></div>`;const hint=hints[Math.min(t,4)];return `<div class="tutorial-card"><span class="tutorial-number">${t+1}</span><div><strong>${hint[0]}</strong><p>${hint[1]}</p></div><span class="tutorial-count">${t+1}/5</span></div>`;}
  panel('brew').innerHTML=`${pageHeading('A PINCH OF POSSIBILITY','The brewer’s bench','Good things begin with a little experimentation.',`<button class="text-button" data-action="forecast">${icon('eye',16)} Form a hypothesis</button>`)}<div id="tutorial-container">${hintHTML()}</div><div id="mobile-commission" class="mobile-commission">${compactCommission()}</div><div class="brew-layout"><div class="workbench"><div class="cauldron-stage"><div class="stage-top"><span class="stage-label"><i></i> YOUR CAULDRON</span><button class="lid-button" data-action="lid" aria-label="Toggle lid">${icon('cauldron',16)}<span data-live="lid">Lid open</span></button></div><canvas id="brew-canvas" aria-label="Interactive cauldron. Drag to stir or crush; choose Pour then tap to add your selected ingredient." role="img"></canvas><div class="stage-bottom"><span data-live="stage-hint">Drag the spoon through your mixture</span><span data-live="phase">Empty vessel</span></div><div class="inspection" data-live="inspection" hidden></div></div><div class="potion-stats"><div><span>${icon('drop',16)} Volume</span><strong><span data-live="mass">0</span><small> ml</small></strong></div><div><span>${icon('fire',16)} Temperature</span><strong><span data-live="temperature">20</span><small> °C</small></strong></div><div><span>${icon('spoon',16)} Mixed</span><strong><span data-live="homogeneity">0</span><small> %</small></strong></div></div><button class="button secondary ingredients-drawer-button full" data-action="ingredients" aria-label="Open ingredients">${icon('leaf',18)}<span>Choose ingredients</span><small>Your shelf, within reach</small>${icon('plus',18)}</button><div class="toolbox"><div class="tool-buttons" role="group" aria-label="Laboratory tools">${(['pour','stir','crush','inspect'] as Tool[]).map(t=>`<button class="tool-button ${t===tool?'active':''}" data-action="tool" data-tool="${t}" aria-pressed="${t===tool}">${icon({pour:'drop',stir:'spoon',crush:'hammer',inspect:'eye'}[t],20)}<span>${nice(t)}</span></button>`).join('')}</div><div class="heat-control"><span class="heat-label">${icon('fire',18)}<strong>Furnace</strong><span data-live="heat">Off</span></span><div class="heat-slider"><button class="icon-button" data-action="cool" aria-label="Cool mixture">${icon('snow',18)}</button><input type="range" id="heat-input" aria-label="Furnace heat" min="-100" max="100" step="5" value="${game.sim.heat*100}"/><button class="icon-button" data-action="warm" aria-label="Heat mixture">${icon('fire',18)}</button></div></div><div class="bench-actions"><button class="button secondary" data-action="navigate" data-tab="trials">${icon('flask',18)} Test a sample</button><button class="button primary" data-action="bottle">${icon('bottle',18)} Bottle mixture</button></div></div><div class="bench-extras"><button class="text-button" data-action="stir-once">${icon('spoon',15)} Stir mixture</button><button class="text-button" data-action="crush-once">${icon('hammer',15)} Crush solids</button><button class="text-button" data-action="distill" id="distill-button" hidden>${icon('flask',15)} Collect distillate</button><button class="text-button" data-action="empty">${icon('drop',15)} Empty cauldron</button></div><div class="reaction-feed" aria-live="polite"><span class="eyebrow">CAULDRON NOTES</span><p data-live="reaction">The vessel is quiet. What will you discover?</p></div><div id="forecast-container" hidden></div></div><aside class="bench-sidebar"><div id="commission-container">${commissionHTML()}</div><div class="inventory-tip">${icon('compass',20)}<p>Running low? The <button class="inline-link" data-action="navigate" data-tab="explore">gathering grounds</button> always have something new.</p></div></aside></div><section class="ingredient-section"><div class="section-heading"><div><span class="eyebrow">A WELL-STOCKED SHELF</span><h2>Your ingredients</h2></div><label class="amount-control">Add amount <select id="add-amount" aria-label="Ingredient amount"><option value="8">8 ml</option><option value="16">16 ml</option><option value="24" selected>24 ml</option><option value="40">40 ml</option></select></label></div><div class="shelf-filters" role="group" aria-label="Ingredient phase">${['all','liquid','powder','solid','paste','gas'].map(p=>`<button class="filter-button ${phase===p?'active':''}" data-action="phase" data-phase="${p}">${nice(p)}</button>`).join('')}</div><div class="ingredient-shelf" id="ingredient-shelf"></div></section><div class="diagnostics" id="diagnostics" hidden></div>`;
  const canvas=root.querySelector<HTMLCanvasElement>('#brew-canvas')!;
  const renderer=new LaboratoryRenderer(canvas,game.sim,game.world);
  function shelfCards(filter=phase){const items=game.world.ingredients.filter(i=>game.isUnlocked(i.id)||game.state.mode==='sandbox').filter(i=>filter==='all'||i.phase===filter);return items.map(i=>{const qty=game.state.inventory[i.id]||0;return `<article class="ingredient-card ${i.id===selected?'selected':''}"><button class="ingredient-info" data-action="ingredient" data-id="${esc(i.id)}" aria-label="Inspect ${esc(i.name)}">${swatch(i)}<span><strong>${esc(i.name)}</strong><small>${esc(i.subtitle)}</small></span><span class="quantity">${num(qty)}<small> ml</small></span></button><div class="ingredient-card-bottom"><div class="effect-chips">${effectChips(i)}</div><button class="add-button" data-action="add" data-id="${esc(i.id)}" aria-label="Add ${esc(i.name)}" ${qty<amount&&game.state.mode!=='sandbox'?'disabled':''}>${icon('plus',15)} Add</button></div></article>`;}).join('')||'<div class="empty-state">No ingredients here yet. Explore the gathering grounds.</div>';}
  function renderShelf(){const html=shelfCards();root.querySelector('#ingredient-shelf')!.innerHTML=html;const drawer=root.querySelector('#drawer-shelf');if(drawer)drawer.innerHTML=shelfCards('all');}
  function compactCommission(){const c=game.state.commission;return `<button class="compact-request" data-action="commission-jump"><span>${icon('shop',17)} <strong>${esc(c.customer)} · ${esc(c.title)}</strong><small>${c.budget}g</small></span><span>${c.requirements.map(r=>`<i>${esc(r.label)} ${r.min!==undefined?'≥ '+num(r.min):'≤ '+num(r.max??r.target??0)}</i>`).join('')}</span></button>`;}
  function gatherCooldown(id:string){return id==='water'||game.state.mode==='sandbox'?0:Math.max(0,Math.ceil((45000-(Date.now()-(game.state.gathered[id]||0)))/1000));}
  function gatheringLabel(id:string){const seconds=gatherCooldown(id);return seconds?`Regrows ${seconds}s`:`Gather +${id==='water'?72:48} ml`;}
  function forestScene(id:string){const marsh=id==='fen',mountain=id==='peaks',ruin=id==='ruins';return `<svg class="forest-scene" viewBox="0 0 1000 520" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${esc(nice(id))} gathering landscape"><defs><linearGradient id="sky-${id}" x2="0" y2="1"><stop stop-color="${marsh?'#c6d1cb':mountain?'#bdd4d5':'#e4e6cc'}"/><stop offset="1" stop-color="#f0eedb"/></linearGradient><linearGradient id="ground-${id}" x2="0" y2="1"><stop stop-color="#738d72"/><stop offset="1" stop-color="#2e584b"/></linearGradient></defs><rect width="1000" height="520" fill="url(#sky-${id})"/><circle cx="740" cy="98" r="52" fill="#fff3cb" opacity=".8"/><path d="M0 275Q150 130 330 240T670 220T1000 230V520H0Z" fill="#a8bca4"/><path d="M0 315Q210 210 390 296T710 285T1000 280V520H0Z" fill="#849e88"/>${mountain?'<path d="m360 292 155-215 164 217 122-165 160 204" fill="#81959a"/><path d="m474 134 41-57 45 59-25-12-15 12-14-16Z" fill="#edf1e8"/>':''}<path d="M0 349Q280 289 440 354T1000 332V520H0Z" fill="url(#ground-${id})"/><path d="M460 520q-84-67 2-114t44-81q74 42 1 88t59 107Z" fill="${marsh?'#94b9b1':'#d4cfab'}" opacity=".85"/>${[35,135,230,805,900,985].map((x,i)=>`<g transform="translate(${x} ${i%2?35:0})"><path d="M-8 400 0 108l9 292Z" fill="#3c6050"/><path d="M-87 322 0 90l87 232-47-21 37 77-77-31-77 31 37-77Z" fill="${i%2?'#496e59':'#557861'}"/><path d="M0 138v216" stroke="#6b896a" stroke-width="3"/></g>`).join('')}${ruin?'<g fill="#a7b3a0"><path d="M640 331V204h26v127Zm115 0V204h26v127Z"/><path d="M629 204h164v25H629Z"/><path d="M660 187h105l28 17H629Z"/></g>':''}<g fill="#dde4bc" opacity=".8"><circle cx="215" cy="434" r="3"/><circle cx="790" cy="402" r="3"/><circle cx="623" cy="451" r="3"/><circle cx="337" cy="393" r="3"/></g><path d="M0 498q80-41 140 0 100-40 140 0 60-45 120 0 100-40 190 0 80-40 160 0 100-40 250 0V520H0Z" fill="#284f43"/></svg>`;}
  function renderExplore(){const regions=game.regions(),active=regions.find(r=>r.id===region)||regions[0];const materials=game.world.ingredients.filter(i=>i.region===active.id&&i.id.indexOf('reaction')!==0);panel('explore').innerHTML=`${pageHeading('BEYOND THE APOTHECARY','The gathering grounds','Fresh ingredients, a quiet path, and a little wild magic.')}<div class="region-tabs">${regions.map(r=>`<button class="region-tab ${r.id===active.id?'active':''}" data-action="region" data-id="${r.id}" ${game.state.reputation<r.reputation?'disabled':''}>${icon(game.state.reputation<r.reputation?'lock':'leaf',18)}<span>${esc(r.name)}${game.state.reputation<r.reputation?`<small>${r.reputation} reputation</small>`:''}</span></button>`).join('')}</div><div class="explore-landscape">${forestScene(active.id)}<div class="landscape-caption"><span class="eyebrow">${esc(active.name)}</span><h2>Take only what you need.</h2><p>${esc(active.description)}</p></div><div class="resource-nodes">${materials.slice(0,6).map((i,n)=>`<button class="resource-node" data-action="gather" data-id="${esc(i.id)}" style="--node-x:${[20,68,42,80,30,57][n]}%;--node-y:${[58,49,68,70,39,35][n]}%;--ingredient:${esc(i.color)}" aria-label="Gather ${esc(i.name)}"><span>${icon(i.phase==='solid'?'leaf':i.phase==='liquid'?'drop':'spark',23)}</span><strong>${esc(i.name)}</strong><small data-gather-time="${esc(i.id)}">${gatheringLabel(i.id)}</small></button>`).join('')}</div></div><div class="explore-footer"><span>${icon('leaf',20)} Gathering is free. Resources regrow with time.</span><span>Your satchel travels with you.</span></div><div class="section-heading"><div><span class="eyebrow">FOUND ALONG THE PATH</span><h2>${esc(active.name)} ingredients</h2></div><button class="text-button" data-action="navigate" data-tab="brew">Return to the bench ${icon('arrow',16)}</button></div><div class="gathering-list">${materials.map(i=>`<article class="gather-card">${swatch(i)}<div><button class="inline-link dark" data-action="ingredient" data-id="${esc(i.id)}">${esc(i.name)}</button><p>${esc(i.subtitle)} · ${num(game.state.inventory[i.id]||0)} ml in satchel</p><div class="effect-chips">${effectChips(i)}</div></div><button class="button secondary" data-action="gather" data-id="${esc(i.id)}" aria-label="Gather ${esc(i.name)}"><span data-gather-time="${esc(i.id)}">${gatheringLabel(i.id)}</span> ${icon('plus',16)}</button></article>`).join('')||'<div class="empty-state">These grounds are still revealing their secrets.</div>'}</div>`;}
  function subjectArt(id:string){const plant=id.includes('seed'),moth=id.includes('moth'),mineral=id.includes('mineral')||id.includes('stone');return `<svg class="subject-art" viewBox="0 0 240 220" aria-hidden="true"><ellipse cx="120" cy="187" rx="80" ry="13" fill="#264c3d" opacity=".08"/>${plant?'<path d="M94 161h52l-8 33h-36Z" fill="#b38b67"/><path d="M120 164v-67" stroke="#638263" stroke-width="5"/><path d="M120 127c-45 0-51-42-51-42 42-1 53 24 51 42Zm0-19c0-46 41-52 41-52 5 35-16 52-41 52Z" fill="#799970"/><path d="M110 90c-23-35 10-58 10-58s34 25 12 59Z" fill="#c1cfa1"/>':moth?'<path d="M116 110C70 24 8 72 43 126c-32 33 30 81 74 24M124 110c46-86 108-38 73 16 32 33-30 81-74 24" fill="#c7b5b6" stroke="#988d9c" stroke-width="2"/><path d="M117 95c-10 24-8 50 3 76 11-26 13-52 3-76Z" fill="#647b70"/><path d="m118 98-10-18m16 18 10-18" stroke="#647b70" stroke-width="2"/><g fill="#f1e7cf"><circle cx="76" cy="106" r="14"/><circle cx="164" cy="106" r="14"/><circle cx="78" cy="151" r="8"/><circle cx="162" cy="151" r="8"/></g>':mineral?'<path d="m74 161 20-83 26-32 34 31 22 84-55 34Z" fill="#b7bcc7"/><path d="m94 78 27 117 33-118-34-31Z" fill="#d8dfde"/><path d="m74 161 47 34-27-117Z" fill="#8f9da9"/><path d="m121 195 55-34-22-84Z" fill="#a6a6be"/>':id.includes('dummy')?'<path d="M109 73h23v113h-23Z" fill="#a88966"/><path d="M70 97h100v20H70Z" fill="#b79773"/><path d="m100 156-21 39m62-39 21 39" stroke="#7e775e" stroke-width="10"/><ellipse cx="120" cy="58" rx="29" ry="34" fill="#c4b691" stroke="#a49574" stroke-width="2"/><path d="M107 46h26v25h-26Z" fill="none" stroke="#967756" stroke-width="2"/><path d="m109 48 22 21m-22 0 22-21" stroke="#967756"/>':'<path d="M78 164c-16-22-8-58 24-68l-12-45 25 22 17-27 7 52c37 11 48 40 26 66-15 17-70 19-87 0Z" fill="#acc4bd"/><path d="M78 156c-43 21-45-34-23-44" stroke="#7d9b8f" stroke-width="9" fill="none"/><ellipse cx="102" cy="127" rx="5" ry="7" fill="#365a4d"/><ellipse cx="144" cy="127" rx="5" ry="7" fill="#365a4d"/><path d="m116 144 7 5 7-5" stroke="#557969" stroke-width="3" fill="none"/><circle cx="166" cy="70" r="5" fill="#cdb470"/><path d="m170 57 4-8m7 21 8-1" stroke="#cdb470" stroke-width="2"/>'}</svg>`;}
  function trialResponse(id:string,e?:Experiment){if(!e)return '';const m=e.metrics;if(id==='moon-seed')return (m.toxicity||0)>20?'response-harm':(m.healing||0)>=30?'response-growth':'';if(id==='training-dummy')return (m.strength||0)>=22?'response-force':(m.protection||0)>=20?'response-ward':'';if(id==='glass-moth')return (m.attraction||0)>=25?'response-flutter':(m.frost||0)>=20?'response-frost':(m.warmth||0)>=15?'response-warmth':'';if(id==='mineral-slate')return (m.acidity??7)<4?'response-harm':(m.transformation||0)>30?'response-shift':'';return (m.energy||0)>=25?'response-energy':(m.transformation||0)>=30?'response-shift':'';}
  function renderTrials(){const current=SUBJECTS.find(s=>s.id===subject)||SUBJECTS[0];const latest=game.state.journal.find(e=>e.subject===current.id);panel('trials').innerHTML=`${pageHeading('WHERE CURIOSITY MEETS EVIDENCE','The trial room','Every subject reveals a different part of your potion’s story.',`<button class="text-button" data-action="navigate" data-tab="brew">Back to brewing ${icon('arrow',16)}</button>`)}<div class="trial-layout"><div><div class="subject-tabs" role="group" aria-label="Experimental subjects">${SUBJECTS.map(s=>`<button class="subject-tab ${s.id===current.id?'active':''}" data-action="subject" data-id="${s.id}" aria-pressed="${s.id===current.id}">${icon(s.id.includes('seed')?'leaf':s.id.includes('moth')?'spark':s.id.includes('dummy')?'hammer':'star',22)}<span>${esc(s.name)}</span></button>`).join('')}</div><div class="subject-stage ${trialResponse(current.id,latest)}"><span class="eyebrow">A CONTROLLED EXPERIMENT</span>${subjectArt(current.id)}<h2>${esc(current.name)}</h2><p>${esc(current.description)}</p><div class="reveal-tags">${current.reveals.map(e=>`<span>${nice(e)}</span>`).join('')}</div><button class="button primary" data-action="test" data-id="${current.id}" aria-label="Test on ${esc(current.name)}" ${metrics().mass<6?'disabled':''}>${icon('flask',19)} Test on ${esc(current.name)}</button><small class="fine-print">Testing consumes a measured sample from the cauldron.</small><span class="sample-volume">${num(metrics().mass)} ml remaining in your cauldron</span></div></div><aside class="trial-report"><div class="section-heading"><div><span class="eyebrow">OBSERVE. COMPARE. REFINE.</span><h2>Field notes</h2></div>${icon('book',26)}</div>${latest?reportHTML(latest):`<div class="report-empty">${icon('flask',44)}<h3>A discovery is waiting.</h3><p>Prepare a mixture at your bench, then take a sample. Measurements appear here after the experiment.</p><button class="button secondary" data-action="navigate" data-tab="brew">Prepare a mixture ${icon('arrow',16)}</button></div>`}<div class="report-advice">${icon('eye',20)}<p>Results describe the sample you tested. Change the mixture and test again to verify your next batch.</p></div></aside></div>`;}
  function reportHTML(e:Experiment){return `<div class="report-body"><span class="report-stamp">${icon('check',16)} EXPERIMENT RECORDED</span><h3>${esc(e.name)}</h3><p class="observation">${esc(e.observation)}</p><div class="results">${resultRows(e.metrics)}</div><button class="button secondary full" data-action="recipe" data-id="${esc(e.id)}">${icon('book',18)} Record a formula</button><button class="text-button full" data-action="navigate" data-tab="journal">Read your full journal ${icon('arrow',16)}</button></div>`;}
  function renderJournal(){panel('journal').innerHTML=`${pageHeading('NOTHING LEARNED IS EVER LOST','The alchemist’s journal','A record of discoveries, difficult batches, and happy accidents.',`<span class="count-badge">${game.state.journal.length} experiments · ${game.state.recipes.length} formulas</span>`)}<div class="journal-tabs">${[['experiments','Experiments'],['recipes','Saved formulas'],['ingredients','Ingredient knowledge'],['reactions','Reactions']].map(([id,label])=>`<button class="filter-button ${journalTab===id?'active':''}" data-action="journal-tab" data-id="${id}">${label}</button>`).join('')}</div>${journalTab==='reactions'?reactionNotebook():journalTab==='ingredients'?`<div class="knowledge-grid">${game.world.ingredients.filter(i=>game.isUnlocked(i.id)||game.state.mode==='sandbox'||game.state.journal.some(e=>e.composition[i.id])).map(i=>`<button class="knowledge-card" data-action="ingredient" data-id="${esc(i.id)}">${swatch(i,true)}<span class="eyebrow">${esc(nice(i.phase))} · ${esc(nice(i.region))}</span><h3>${esc(i.name)}</h3><p>${esc(i.description)}</p><span class="effect-chips">${effectChips(i)}</span><span class="knowledge-link">Examine properties ${icon('arrow',14)}</span></button>`).join('')}</div>`:journalTab==='recipes'?`<div class="journal-entries">${game.state.recipes.length?game.state.recipes.map(r=>`<article class="journal-entry recipe-entry"><div class="entry-icon">${icon('book',25)}</div><div><span class="eyebrow">PERSONAL FORMULA</span><h2>${esc(r.name)}</h2><div class="composition-list"><strong>Measured sample proportions:</strong> ${Object.entries(r.composition).map(([id,v])=>`${esc(ingredient(id)?.name||nice(id))}: ${num(v,1)} ml`).join(' · ')}</div><ol class="recipe-steps">${r.steps.map(step=>`<li>${esc(step)}</li>`).join('')||'<li>Add your materials and test as you refine the preparation.</li>'}</ol><div class="results compact">${resultRows(r.metrics)}</div><p class="fine-print">A formula is a preparation guide. Follow the quantities and steps manually at your bench.</p><button class="button quiet" data-action="navigate" data-tab="brew">Prepare at the bench ${icon('arrow',16)}</button></div></article>`).join(''):emptyHTML('book','Your own little book of wonders.','Record a tested preparation from the trial room. Name it, keep its steps, and make it your own.','Visit the trial room','trials')}</div>`:`<div class="journal-entries">${game.state.journal.length?game.state.journal.map(e=>`<article class="journal-entry"><div class="entry-icon">${icon('flask',25)}</div><div><span class="eyebrow">${esc(SUBJECTS.find(s=>s.id===e.subject)?.name||nice(e.subject))}</span><h2>${esc(e.name)}</h2><p>${esc(e.observation)}</p><div class="results compact">${resultRows(e.metrics)}</div><details><summary>Preparation notes</summary><div class="composition-list">${Object.entries(e.composition).map(([id,v])=>`${esc(ingredient(id)?.name||nice(id))}: ${num(v,1)} ml`).join(' · ')}</div><ol class="recipe-steps">${e.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details><button class="text-button" data-action="recipe" data-id="${esc(e.id)}">${icon('book',16)} Record a formula</button></div></article>`).join(''):emptyHTML('flask','A clean page. A thousand possibilities.','Your experiments will appear here, including the batches that surprised you.','Make your first discovery','trials')}</div>`}`;}
  function reactionNotebook(){const discovered=game.world.reactions.filter(r=>game.state.journal.some(e=>(e.composition[r.product]||0)>0)||game.sim.events.some(event=>event.startsWith(r.name)));return `<div class="journal-entries">${discovered.length?discovered.map(r=>`<article class="journal-entry"><div class="entry-icon">${icon('spark',25)}</div><div><span class="eyebrow">OBSERVED MATERIAL TRANSFORMATION</span><h2>${esc(r.name)}</h2><p>${esc(r.clue)}</p><div class="reaction-formula"><span>${esc(ingredient(r.a)?.name||nice(r.a))}</span><b>+</b><span>${esc(ingredient(r.b)?.name||nice(r.b))}</span>${icon('arrow',16)}<span>${esc(ingredient(r.product)?.name||nice(r.product))}</span></div><p class="fine-print">Discovered through a real transformation in your vessel. Temperature, contact, and preparation determine whether it happens again.</p><button class="text-button" data-action="navigate" data-tab="brew">Investigate at the bench ${icon('arrow',16)}</button></div></article>`).join(''):emptyHTML('spark','Some secrets take a little patience.','Materials can form something new when they meet under the right conditions. Observed transformations will appear here.','Try a new preparation','brew')}</div>`;}
  function emptyHTML(symbol:string,title:string,description:string,action:string,destination:Tab){return `<div class="empty-state">${icon(symbol,42)}<h2>${title}</h2><p>${description}</p><button class="button secondary" data-action="navigate" data-tab="${destination}">${action} ${icon('arrow',16)}</button></div>`;}
  function bottleEvidence(signature:string){const evidence:Partial<PotionMetrics>={};for(const e of [...game.state.journal].reverse())if(e.signature===signature)Object.assign(evidence,e.metrics);const known=EFFECTS.filter(e=>evidence[e]!==undefined).slice(0,3);return known.length?known.map(e=>`<span>${nice(e)} ${num(evidence[e]!)}</span>`).join(''):'<span>Unverified effects · test before bottling</span>';}
  function renderShop(){const c=game.state.commission;panel('shop').innerHTML=`${pageHeading('SMALL BOTTLES. GREAT POSSIBILITIES.','The apothecary shop','Deliver your best work, stock the shelf, and grow your craft.',`<span class="shop-wallet">${icon('coin',24)} ${num(game.state.coins)} <small>gold</small></span>`)}<div class="shop-layout"><div class="delivery-section"><div class="section-heading"><div><span class="eyebrow">READY FOR ${esc(c.customer).toUpperCase()}</span><h2>Your bottled potions</h2></div><span class="count-badge">${game.state.bottles.length} bottles</span></div><div class="bottle-list">${game.state.bottles.length?game.state.bottles.map(b=>`<article class="bottle-card"><div class="bottle-art">${icon('bottle',42)}</div><div><h3>${esc(b.name)}</h3><p>${num(b.sample.mass)} ml · ${num(b.sample.metrics.temperature)}°C · ${num(b.sample.metrics.homogeneity*100)}% mixed</p><div class="bottle-effects">${bottleEvidence(b.sample.signature)}</div><button class="button primary" data-action="sell" data-id="${esc(b.id)}" aria-label="Sell ${esc(b.name)}">${icon('coin',16)} Deliver to customer</button></div></article>`).join(''):emptyHTML('bottle','Your next customer is waiting.','Bottle a tested mixture at your bench, then return here to deliver it.','Back to the bench','brew')}</div></div><aside>${commissionHTML()}</aside></div><section class="shop-upgrades"><div class="section-heading"><div><span class="eyebrow">TOOLS OF THE TRADE</span><h2>Improve your laboratory</h2></div></div><div class="upgrade-grid">${UPGRADES.map((u,n)=>{const owned=game.state.upgrades.includes(u.id),locked=game.state.reputation<u.reputation;return `<article class="upgrade-card"><span class="upgrade-icon">${icon(['cauldron','fire','snow','spoon','eye','flask'][n]||'gear',25)}</span><div><h3>${esc(u.name)}</h3><p>${esc(u.description)}</p></div><button class="button ${owned?'quiet':'secondary'}" data-action="upgrade" data-id="${u.id}" aria-label="Purchase ${esc(u.name)}" ${owned||locked||game.state.coins<u.price?'disabled':''}>${owned?`${icon('check',16)} Installed`:locked?`${icon('lock',15)} ${u.reputation} reputation`:`${icon('coin',15)} ${u.price} gold`}</button></article>`;}).join('')}</div></section><section class="supply-section"><div class="section-heading"><div><span class="eyebrow">THE TRAVELLING MERCHANT</span><h2>Replenish your shelf</h2></div><span class="fine-print">24 ml per purchase</span></div><div class="supply-grid">${game.world.ingredients.filter(i=>game.isUnlocked(i.id)).filter(i=>i.price>0).map(i=>`<article class="supply-card">${swatch(i)}<div><button class="inline-link dark" data-action="ingredient" data-id="${esc(i.id)}">${esc(i.name)}</button><small>${num(game.state.inventory[i.id]||0)} ml in stock</small></div><button class="button quiet" data-action="buy" data-id="${esc(i.id)}" aria-label="Buy ${esc(i.name)}">${icon('coin',15)} ${i.price}g</button></article>`).join('')}</div></section><section class="shop-progress"><span class="eyebrow">YOUR CRAFT IS GROWING</span><h2>${esc(game.rank)}</h2><p>${game.state.sales} commissions delivered · ${game.state.reputation} reputation · ${game.state.achievements.length} milestones earned</p><div class="milestones">${game.state.achievements.map(a=>`<span>${icon('check',14)}${esc(nice(a))}</span>`).join('')}</div><p class="fine-print">Gathering paths open at 12, 35, and 70 reputation. Consistent, carefully tested commissions bring the best rewards.</p></section>`;}
  function navigate(next:Tab){tab=next;root.querySelectorAll<HTMLElement>('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==tab);root.querySelectorAll<HTMLElement>('.nav-button').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(tab==='explore')renderExplore();if(tab==='trials')renderTrials();if(tab==='journal')renderJournal();if(tab==='shop')renderShop();hooks.sound('tap');}
  function refreshViews(){renderShelf();root.querySelector('#mobile-commission')!.innerHTML=compactCommission();root.querySelector('#commission-container')!.innerHTML=commissionHTML();root.querySelector('#tutorial-container')!.innerHTML=hintHTML();if(tab==='explore')renderExplore();if(tab==='trials')renderTrials();if(tab==='journal')renderJournal();if(tab==='shop')renderShop();if(showForecast)renderForecast();}
  function renderForecast(){const container=root.querySelector<HTMLElement>('#forecast-container')!;container.hidden=!showForecast;if(showForecast)container.innerHTML=`<div class="forecast-card"><div><span class="eyebrow">YOUR WORKING HYPOTHESIS</span><button class="icon-button" data-action="forecast" aria-label="Close hypothesis">${icon('close',16)}</button></div><h3>What might this mixture do?</h3><p>Known ingredient properties suggest these effects. Reactions and preparation can change the outcome: an experiment is your evidence.</p><div class="results">${resultRows(game.predict())}</div></div>`;}
  function toast(message:string){if(!message)return;lastMessage=message;const el=root.querySelector<HTMLElement>('#toast-message')!;el.textContent=message;el.classList.add('visible');window.clearTimeout(toastTimeout);toastTimeout=window.setTimeout(()=>el.classList.remove('visible'),4500);}
  function changed(sound='tap'){hooks.save();hooks.sound(sound);refreshViews();if(game.lastMessage)toast(game.lastMessage);}
  function showModal(type:string,id=''){if(!modal)opener=document.activeElement as HTMLElement;modal=type;modalId=id;const layer=root.querySelector<HTMLElement>('#modal-layer')!;layer.hidden=false;let content='';let title='';
    if(type==='ingredients'){title='Your ingredient shelf';content=`<span class="eyebrow">A PINCH OF POSSIBILITY</span><h2>${title}</h2><p>Choose a measured amount and add it directly to your cauldron.</p><label class="amount-control drawer-amount">Add amount <select id="drawer-amount" aria-label="Drawer ingredient amount">${[8,16,24,40].map(n=>`<option value="${n}" ${n===amount?'selected':''}>${n} ml</option>`).join('')}</select></label><div class="ingredient-shelf drawer-shelf" id="drawer-shelf">${shelfCards('all')}</div><button class="button primary full" data-action="close-modal">Return to cauldron ${icon('arrow',16)}</button>`;}
    if(type==='settings'){title='Make yourself at home';content=`<span class="eyebrow">APOTHECARY SETTINGS</span><h2>${title}</h2><div class="setting-row"><label for="sound-setting">${icon('volume',20)}<span>Brewing sounds<small>A little atmosphere for your workbench</small></span></label><input type="checkbox" id="sound-setting" ${game.state.settings.sound?'checked':''}/></div><label class="setting-block">Volume<input type="range" id="volume-setting" min="0" max="100" value="${game.state.settings.volume*100}" aria-label="Sound volume"/></label><label class="setting-row">Rendering quality<select id="quality-setting"><option value="auto" ${game.state.settings.quality==='auto'?'selected':''}>Adaptive</option><option value="low" ${game.state.settings.quality==='low'?'selected':''}>Low</option><option value="high" ${game.state.settings.quality==='high'?'selected':''}>High</option></select></label><label class="setting-row">Reduced motion<input type="checkbox" id="motion-setting" ${game.state.settings.reducedMotion?'checked':''}/></label><label class="setting-row">Show performance<input type="checkbox" id="diagnostics-setting" ${diagnostics?'checked':''}/></label><div class="settings-divider"></div><div class="setting-row"><span><strong>Free experimentation</strong><small>Unlimited materials in the sandbox</small></span><button class="button secondary" data-action="mode">${game.state.mode==='sandbox'?'Return to shop':'Enter sandbox'}</button></div><div class="settings-divider"></div><span class="eyebrow">YOUR WORLD</span><p class="seed-value">Seed: <strong>${esc(game.state.seed)}</strong></p><label class="setting-block">New world seed<input type="text" id="world-seed" maxlength="80" placeholder="Give your world a name" /></label><button class="button quiet full" data-action="new-world">Create a new world ${icon('arrow',16)}</button><p class="fine-print">A new world replaces this local game. Export your save first to keep it.</p><div class="settings-divider"></div><div class="settings-save-actions"><button class="button secondary" data-action="export">${icon('download',17)} Export save</button><button class="button secondary" data-action="import">${icon('upload',17)} Import save</button></div><p class="fine-print">Your progress is saved automatically on this device.</p>`;}
    if(type==='ingredient'){const i=ingredient(id);if(!i)return;const learned:Partial<PotionMetrics>={};if(i.region==='laboratory'){for(const entry of [...game.state.journal].reverse()){const total=Object.values(entry.composition).reduce((sum,value)=>sum+value,0);if(total>0&&(entry.composition[i.id]||0)/total>.99)Object.assign(learned,entry.metrics);}}title=i.name;content=`<div class="ingredient-modal-heading">${swatch(i,true)}<span class="eyebrow">${nice(i.phase)} · ${nice(i.region)}</span><h2>${esc(i.name)}</h2><p>${esc(i.description)}</p><div class="effect-chips">${effectChips(i)}</div></div><span class="eyebrow">KNOWN MAGICAL PROPERTIES</span><div class="results">${i.region==='laboratory'?(Object.keys(learned).length?resultRows(learned):'<p class="fine-print">This newly formed compound has unknown magic. Test a sample to learn its properties.</p>'):resultRows(i.effects)}</div><span class="eyebrow">MATERIAL NOTES</span><dl class="material-properties"><div><dt>Density</dt><dd>${num(i.density,2)}</dd></div><div><dt>Viscosity</dt><dd>${num(i.viscosity,2)}</dd></div><div><dt>Solubility</dt><dd>${num(i.solubility,2)}</dd></div><div><dt>Melts at</dt><dd>${num(i.melting)}°C</dd></div><div><dt>Boils at</dt><dd>${num(i.boiling)}°C</dd></div><div><dt>Acidity</dt><dd>${num(i.acidity,1)}</dd></div><div><dt>Compatibility</dt><dd>${esc(nice(i.miscibility))}</dd></div><div><dt>Stability</dt><dd>${num(i.stability,1)}</dd></div></dl><p class="fine-print">Ingredient effects are clues. The preparation, concentration, and unknown reactions shape a finished potion.</p><button class="button primary full" data-action="select" data-id="${esc(i.id)}">${icon('drop',18)} Select for pouring · ${num(game.state.inventory[i.id]||0)} ml in stock</button>`;}
    if(type==='recipe'){title='A discovery worth naming';content=`<span class="eyebrow">YOUR PERSONAL FORMULA</span><h2>${title}</h2><p>Record the ingredients, preparation notes, and observations from this experiment.</p><label class="setting-block">Formula name<input id="recipe-name" type="text" maxlength="60" placeholder="A small wonder" value=""/></label><button class="button primary full" data-action="save-recipe" data-id="${esc(id)}">${icon('book',18)} Save formula</button>`;}
    if(type==='empty'){title='A fresh vessel?';content=`<span class="eyebrow">CLEAR THE CAULDRON</span><h2>${title}</h2><p>Empty this mixture to begin a new preparation. The materials already added will be discarded.</p><button class="button primary full" data-action="confirm-empty">Empty mixture</button>`;}
    if(type==='new-world'){title='Begin a new story?';const seed=root.querySelector<HTMLInputElement>('#world-seed')?.value||'';modalId=seed;content=`<span class="eyebrow">A FRESH APOTHECARY</span><h2>${title}</h2><p>Your current ingredients, discoveries, and progress will be replaced on this device.</p><p>New seed: <strong>${esc(seed||'A fresh random world')}</strong></p><div class="settings-save-actions"><button class="button secondary" data-action="export">${icon('download',17)} Export current save</button><button class="button primary" data-action="confirm-world">Create new world</button></div>`;}
    layer.innerHTML=`<div class="modal-backdrop" data-action="close-modal"></div><section class="modal-dialog" id="app-settings" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="icon-button modal-close" data-action="close-modal" aria-label="Close ${type==='settings'?'settings':'dialog'}">${icon('close',21)}</button>${content}</section>`;
    window.setTimeout(()=>layer.querySelector<HTMLElement>('input[type="text"],button')?.focus(),0);
  }
  function closeModal(){modal='';root.querySelector<HTMLElement>('#modal-layer')!.hidden=true;opener?.focus();opener=null;}
  function handleClick(event:Event){const button=(event.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!button||button instanceof HTMLButtonElement&&button.disabled)return;const action=button.dataset.action,id=button.dataset.id||'';switch(action){
    case 'navigate':navigate(button.dataset.tab as Tab);break;
    case 'ingredients':showModal('ingredients');break;
    case 'commission-jump':root.querySelector('#commission-container')!.scrollIntoView({behavior:game.state.settings.reducedMotion?'instant':'smooth',block:'start'});break;
    case 'settings':showModal('settings');break;
    case 'close-modal':closeModal();break;
    case 'tool':tool=button.dataset.tool as Tool;root.querySelectorAll<HTMLElement>('.tool-button').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool));});hooks.sound('tap');break;
    case 'phase':phase=button.dataset.phase!;root.querySelectorAll<HTMLElement>('.shelf-filters button').forEach(b=>b.classList.toggle('active',b.dataset.phase===phase));renderShelf();break;
    case 'ingredient':showModal('ingredient',id);break;
    case 'select':selected=id;tool='pour';closeModal();renderShelf();root.querySelectorAll<HTMLElement>('.tool-button').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool));});navigate('brew');toast(`${ingredient(id)?.name||'Ingredient'} selected. Tap the cauldron to pour ${amount} ml.`);break;
    case 'add':selected=id;game.addIngredient(id,amount);changed('pour');break;
    case 'stir-once':for(let y=30;y<=48;y+=6)for(let x=17;x<=47;x+=6)game.stir(x,y,6,Math.sin(x/7)*4);changed('stir');break;
    case 'crush-once':for(let y=37;y<=49;y+=6)for(let x=19;x<=45;x+=6)game.crush(x,y);changed('crush');break;
    case 'empty':showModal('empty');break;
    case 'confirm-empty':game.emptyCauldron();root.querySelector<HTMLInputElement>('#heat-input')!.value='0';closeModal();changed();break;
    case 'distill':game.distill();changed('bottle');break;
    case 'lid':game.toggleLid();changed();break;
    case 'cool':game.setHeat(-1);root.querySelector<HTMLInputElement>('#heat-input')!.value='-100';changed('heat');break;
    case 'warm':game.setHeat(Math.min(1,game.sim.heat+.25));root.querySelector<HTMLInputElement>('#heat-input')!.value=String(game.sim.heat*100);changed('heat');break;
    case 'bottle':{const bottle=game.bottle();changed('bottle');if(bottle)toast(`${bottle.name} is bottled. Deliver it in the shop.`);break;}
    case 'forecast':showForecast=!showForecast;renderForecast();break;
    case 'region':region=id;renderExplore();hooks.sound('tap');break;
    case 'gather':game.gather(region,id);changed('gather');break;
    case 'subject':subject=id;renderTrials();hooks.sound('tap');break;
    case 'test':game.test(id);changed('test');break;
    case 'journal-tab':journalTab=id;renderJournal();break;
    case 'recipe':showModal('recipe',id);break;
    case 'save-recipe':{const name=root.querySelector<HTMLInputElement>('#recipe-name')?.value.trim()||'A small wonder';game.saveRecipe(name,id);closeModal();changed('success');break;}
    case 'sell':game.sell(id);changed('success');break;
    case 'buy':game.buyIngredient(id,24);changed('coin');break;
    case 'upgrade':game.buyUpgrade(id);changed('success');break;
    case 'mode':game.switchMode(game.state.mode==='sandbox'?'shop':'sandbox');changed();showModal('settings');break;
    case 'export':hooks.exportSave();toast('Your apothecary save has been exported.');break;
    case 'import':root.querySelector<HTMLInputElement>('#save-file')!.click();break;
    case 'new-world':showModal('new-world');break;
    case 'confirm-world':hooks.newWorld(modalId||`moonlit-${Date.now().toString(36)}`);break;
  }}
  function handleInput(event:Event){const el=event.target as HTMLInputElement|HTMLSelectElement;switch(el.id){
    case 'heat-input':game.setHeat(Number(el.value)/100);hooks.save();break;
    case 'add-amount':case 'drawer-amount':amount=Number(el.value);root.querySelector<HTMLSelectElement>('#add-amount')!.value=String(amount);renderShelf();break;
    case 'sound-setting':game.state.settings.sound=(el as HTMLInputElement).checked;hooks.save();if(game.state.settings.sound)hooks.sound('tap');break;
    case 'volume-setting':game.state.settings.volume=Number(el.value)/100;hooks.setVolume(game.state.settings.volume);hooks.save();break;
    case 'quality-setting':game.state.settings.quality=el.value as 'auto'|'low'|'high';hooks.save();break;
    case 'motion-setting':game.state.settings.reducedMotion=(el as HTMLInputElement).checked;hooks.save();break;
    case 'diagnostics-setting':diagnostics=(el as HTMLInputElement).checked;root.querySelector<HTMLElement>('#diagnostics')!.hidden=!diagnostics;break;
    case 'save-file':{const file=(el as HTMLInputElement).files?.[0];if(file){hooks.importSave(file);closeModal();}el.value='';break;}
  }}
  const onDown=(e:PointerEvent)=>{if(tab!=='brew')return;pointer=renderer.toGrid(e.clientX,e.clientY);lastPointer=pointer;dragging=true;canvas.setPointerCapture(e.pointerId);if(tool==='pour'){game.addIngredient(selected,amount,pointer.x);changed('pour');}else if(tool==='crush'){game.crush(pointer.x,pointer.y);hooks.sound('crush');}else if(tool==='inspect')inspect(pointer);else hooks.sound('stir');e.preventDefault();};
  const onMove=(e:PointerEvent)=>{pointer=renderer.toGrid(e.clientX,e.clientY);if(dragging&&lastPointer){if(tool==='stir')game.stir(pointer.x,pointer.y,pointer.x-lastPointer.x,pointer.y-lastPointer.y);else if(tool==='crush')game.crush(pointer.x,pointer.y);else if(tool==='inspect')inspect(pointer);lastPointer=pointer;}else if(tool==='inspect')inspect(pointer);};
  const onUp=()=>{if(dragging){dragging=false;lastPointer=null;hooks.save();root.querySelector('#tutorial-container')!.innerHTML=hintHTML();}};
  const onLeave=()=>{if(!dragging)pointer=null;};
  function inspect(p:{x:number;y:number}){const x=Math.floor(p.x),y=Math.floor(p.y);const cell=x>=0&&x<game.sim.width&&y>=0&&y<game.sim.height?game.sim.cells[y*game.sim.width+x]:null;const box=root.querySelector<HTMLElement>('[data-live="inspection"]')!;box.hidden=false;box.textContent=cell?`${nice(cell.phase)} · ${num(cell.temperature)}°C · ${Object.keys(cell.composition).map(id=>ingredient(id)?.name||nice(id)).join(', ')}`:'Empty space — try a different point in the vessel.';}
  function keyboard(e:KeyboardEvent){if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal){const nodes=[...root.querySelectorAll<HTMLElement>('.modal-dialog button,.modal-dialog input,.modal-dialog select')].filter(el=>!(el as HTMLButtonElement).disabled);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}}
  const brand=root.querySelector<HTMLAnchorElement>('.brand')!;const home=(e:Event)=>{e.preventDefault();navigate('brew');};brand.addEventListener('click',home);
  root.addEventListener('click',handleClick);root.addEventListener('input',handleInput);root.addEventListener('change',handleInput);document.addEventListener('keydown',keyboard);canvas.addEventListener('pointerdown',onDown);canvas.addEventListener('pointermove',onMove);canvas.addEventListener('pointerup',onUp);canvas.addEventListener('pointercancel',onUp);canvas.addEventListener('pointerleave',onLeave);
  renderShelf();
  function setLive(name:string,value:string){const el=root.querySelector<HTMLElement>(`[data-live="${name}"]`);if(el&&el.textContent!==value)el.textContent=value;}
  return {update(dt:number){elapsed+=dt;refresh+=dt;fps+=(1/Math.max(dt,.001)-fps)*.05;renderer.sim=game.sim;if(tab==='brew')renderer.render(performance.now(),{tool,quality:game.state.settings.quality==='auto'?(document.documentElement.dataset.renderQuality||'high'):game.state.settings.quality,pointer,selectedColor:ingredient(selected)?.color,reducedMotion:game.state.settings.reducedMotion});if(refresh<.25)return;refresh=0;const m=metrics();setLive('coins',num(game.state.coins));setLive('day',String(game.state.day));setLive('reputation',num(game.state.reputation));setLive('rank',game.rank);setLive('mode',game.state.mode==='sandbox'?'SANDBOX':'SHOP OPEN');setLive('mass',num(m.mass));setLive('temperature',num(m.temperature));setLive('homogeneity',num(m.homogeneity*100));setLive('lid',game.sim.lid?'Lid closed':'Lid open');setLive('heat',game.sim.heat<-.02?'Cooling':game.sim.heat>.02?`${num(game.sim.heat*100)}%`:'Off');setLive('stage-hint',({pour:`Tap to pour ${amount} ml of ${ingredient(selected)?.name||'your selected ingredient'}`,stir:'Drag the spoon through your mixture',crush:'Press and drag to crush solid materials',inspect:'Touch a material to examine its local properties'})[tool]);setLive('phase',m.mass>0?`${num(m.viscosity,1)} viscosity`:'Empty vessel');const events=game.sim.events;setLive('reaction',events[events.length-1]||'The vessel is quiet. What will you discover?');const box=root.querySelector<HTMLElement>('[data-live="inspection"]')!;if(tool!=='inspect')box.hidden=true;const bottle=root.querySelector<HTMLButtonElement>('[data-action="bottle"]')!;bottle.disabled=m.mass<12;root.querySelector<HTMLElement>('#distill-button')!.hidden=!game.state.upgrades.includes('distillery');const verification=requestRows();if(verification!==lastVerification){root.querySelectorAll('.request-table').forEach(el=>el.innerHTML=verification);lastVerification=verification};const diag=root.querySelector<HTMLElement>('#diagnostics')!;if(diagnostics)diag.textContent=`${num(fps)} FPS · ${game.sim.cells.filter(Boolean).length} active cells · ${num(elapsed)}s session · seed ${game.state.seed}`;if(tab==='explore')root.querySelectorAll<HTMLElement>('[data-gather-time]').forEach(el=>{const id=el.dataset.gatherTime!;el.textContent=gatheringLabel(id);const button=el.closest<HTMLButtonElement>('button');if(button)button.disabled=gatherCooldown(id)>0;});if(game.lastMessage&&game.lastMessage!==lastMessage)toast(game.lastMessage);root.classList.toggle('reduced-motion',game.state.settings.reducedMotion);},destroy(){window.clearTimeout(toastTimeout);root.removeEventListener('click',handleClick);root.removeEventListener('input',handleInput);root.removeEventListener('change',handleInput);document.removeEventListener('keydown',keyboard);brand.removeEventListener('click',home);canvas.removeEventListener('pointerdown',onDown);canvas.removeEventListener('pointermove',onMove);canvas.removeEventListener('pointerup',onUp);canvas.removeEventListener('pointercancel',onUp);canvas.removeEventListener('pointerleave',onLeave);renderer.destroy();}};
}
